import { resolve } from 'node:path';
import { getLocalPackageVersion } from '@sanity/cli-core/package-manager';
import { SANITY_INSTALLATION_CONFIG, SANITY_STUDIO } from '../../constants.js';
/**
 * Stamps the installed `sanity` version onto each media-library config resource and studio resource.
 */
export const stampConfigVersion = async (resource, blueprintFileDir) => {
    let update;
    let root;
    if (resource.type === SANITY_INSTALLATION_CONFIG) {
        const config = resource;
        if (config.appType !== 'media-library')
            return;
        // Leave values included in the blueprint.
        if (config.version !== undefined)
            return;
        root = config.root;
        update = (version) => {
            config.version = version;
        };
    }
    else if (resource.type === SANITY_STUDIO) {
        const config = resource;
        // Leave values included in the blueprint.
        if (config.autoUpdates?.version !== undefined)
            return;
        root = config.root;
        update = (version) => {
            if (config.autoUpdates) {
                config.autoUpdates.version = version;
            }
            else {
                config.autoUpdates = { enabled: true, version };
            }
        };
    }
    if (update && root) {
        const workDir = resolve(blueprintFileDir, root);
        const version = await getLocalPackageVersion('sanity', workDir);
        if (!version) {
            throw new Error(`Unable to determine the installed 'sanity' version for resource '${resource.name}'; is 'sanity' installed in '${root}'?`);
        }
        update(version);
    }
};
